I=lambda n:[[int(i==j)for j in range(n)]for i in range(n)]
def closure(M,identity=False):
 a=[row[:]for row in M];n=len(a)
 if identity:
  for i in range(n):a[i][i]=1
 for k in range(n):
  for i in range(n):
   for j in range(n):a[i][j]=int(a[i][j]or a[i][k]and a[k][j])
 return a
def symmetric(M):return [[int(M[i][j]or M[j][i])for j in range(len(M))]for i in range(len(M))]
def frompairs(n,pairs):return [[int((i,j)in pairs)for j in range(n)]for i in range(n)]
def equiv(blocks,n):return [[int(any(i in b and j in b for b in blocks))for j in range(n)]for i in range(n)]
